$insertStatement = $db->prepareQuery("
    INSERT INTO pastoral (
        owner_id, 
        student_id, 
        type_id, 
        heading, 
        body_public, 
        modified_by_user_id, 
        created_at, 
        updated_at
    ) VALUES (
        :owner_id,
        :student_id,
        (SELECT value FROM config WHERE name = 'tigs_crp_pastoral_type'),
        :heading,
        :body_public,
        :modified_by_user_id,
        :created_at,
        :updated_at
    )
");

foreach ($data as $rowId => $row) {
    if (0 === $rowId) {
        // Ignore headers
        continue;
    }
    [$deanId, $studentId, $surname, $preferred, $comment] = $row;
    $dean    = $userMapper->findByExternalId($deanId);
    $student = $userMapper->findByExternalId($studentId);

    // Sanity check
    if ($student->getLastname() !== $surname) {
        echo "Lastname: {$student->getLastname()}, Surname: {$surname}<br>\n";
    }
    if ($student->getFirstname() !== $preferred) {
        echo "Lastname: {$student->getFirstname()}, Surname: {$preferred}<br>\n";
    }

    $insertStatement->execute([
        'owner_id'            => $dean->getId(),
        'student_id'          => $student->getId(),
        'heading'             => "Year 7 2019 Semester 1 Dean's Comment",
        'body_public'         => $comment,
        'modified_by_user_id' => $dean->getId(),
        'created_at'          => $date->getDatabase(),
        'updated_at'          => $date->getDatabase(),
    ]);
}

die('done');
